static const char k_film_deblock_glsl[] =
    "// BO-136 film filters: the parameters every pass takes (the same block as\n"
    "// the texture upscaler's passes, so both backends bind them alike). MIT.\n"
    "#version 450\n"
    "layout(push_constant) uniform UpParams {\n"
    "    ivec2 origin;   // unused here (whole-image dispatches)\n"
    "    ivec2 size;     // the input image's size\n"
    "    ivec2 wrap;     // unused: films clamp to the edge\n"
    "    int   mode;\n"
    "    int   pad0;\n"
    "} pc;\n"
    "\n"
    "layout(local_size_x = 16, local_size_y = 16) in;\n"
    "\n"
    "ivec2 edge(ivec2 p, ivec2 s)\n"
    "{\n"
    "    return clamp(p, ivec2(0), s - ivec2(1));\n"
    "}\n"
    "\n"
    "// A light deblock of a film frame (BO-136; the WMV2 frames' 8x8 block\n"
    "// edges). Own code, MIT. Port of the BO-136 probe's deblock8.hook to the\n"
    "// decoded RGB frame: in YCbCr (BT.601, as the film was coded), the step\n"
    "// across a block edge is spread as a ramp over half a block on each side,\n"
    "// but only where the step is small and both sides are flat (a real edge is\n"
    "// left alone). Luma on the 8-texel grid with its own thresholds; chroma\n"
    "// (4:2:0, so one chroma texel is two of these) on the same grid with taps\n"
    "// one chroma texel apart and lower thresholds.\n"
    "// mode 0: vertical edges, source (binding 0) -> destination;\n"
    "// mode 1: horizontal edges, aux (binding 1) -> destination.\n"
    "layout(set = 0, binding = 0) uniform sampler2D source;\n"
    "layout(set = 0, binding = 1, rgba16f) readonly uniform image2D aux;\n"
    "layout(set = 0, binding = 4, rgba16f) writeonly uniform image2D destination;\n"
    "\n"
    "vec4 tap(ivec2 p)\n"
    "{\n"
    "    p = edge(p, pc.size);\n"
    "    return pc.mode == 0 ? texelFetch(source, p, 0) : imageLoad(aux, p);\n"
    "}\n"
    "\n"
    "const mat3 TO_YCC = mat3( 0.299,     -0.168736,  0.5,\n"
    "                          0.587,     -0.331264, -0.418688,\n"
    "                          0.114,      0.5,      -0.081312);\n"
    "const mat3 TO_RGB = mat3( 1.0,        1.0,       1.0,\n"
    "                          0.0,       -0.344136,  1.772,\n"
    "                          1.402,     -0.714136,  0.0);\n"
    "\n"
    "void main()\n"
    "{\n"
    "    ivec2 p = ivec2(gl_GlobalInvocationID.xy);\n"
    "    if (any(greaterThanEqual(p, pc.size)))\n"
    "        return;\n"
    "    ivec2 ax = pc.mode == 0 ? ivec2(1, 0) : ivec2(0, 1);\n"
    "    int r = (pc.mode == 0 ? p.x : p.y) & 7;\n"
    "    // e: from this texel to q0, the first texel past the nearest block edge.\n"
    "    int e;\n"
    "    float w;\n"
    "    if (r < 4) { e = -r;    w = -(1.0 - float(r) / 4.0) * 0.25; }\n"
    "    else       { e = 8 - r; w =  (1.0 - float(7 - r) / 4.0) * 0.25; }\n"
    "    vec4 c4 = tap(p);\n"
    "    vec3 c = TO_YCC * c4.rgb;\n"
    "    vec3 p0 = TO_YCC * tap(p + ax * (e - 1)).rgb;\n"
    "    vec3 q0 = TO_YCC * tap(p + ax * e).rgb;\n"
    "    vec3 p1 = TO_YCC * tap(p + ax * (e - 2)).rgb;\n"
    "    vec3 q1 = TO_YCC * tap(p + ax * (e + 1)).rgb;\n"
    "    vec3 p1c = TO_YCC * tap(p + ax * (e - 3)).rgb;\n"
    "    vec3 q1c = TO_YCC * tap(p + ax * (e + 2)).rgb;\n"
    "    vec3 d = q0 - p0;\n"
    "    if (abs(d.x) < 0.1 && abs(p1.x - p0.x) < 0.05 && abs(q1.x - q0.x) < 0.05)\n"
    "        c.x += d.x * w;\n"
    "    if (all(lessThan(abs(d.yz), vec2(0.06))) && all(lessThan(abs(p1c.yz - p0.yz), vec2(0.03)))\n"
    "            && all(lessThan(abs(q1c.yz - q0.yz), vec2(0.03))))\n"
    "        c.yz += d.yz * w;\n"
    "    imageStore(destination, p, vec4(clamp(TO_RGB * c, 0.0, 1.0), c4.a));\n"
    "}\n";

static const char k_film_easu_glsl[] =
    "// BO-136 film filters: the parameters every pass takes (the same block as\n"
    "// the texture upscaler's passes, so both backends bind them alike). MIT.\n"
    "#version 450\n"
    "layout(push_constant) uniform UpParams {\n"
    "    ivec2 origin;   // unused here (whole-image dispatches)\n"
    "    ivec2 size;     // the input image's size\n"
    "    ivec2 wrap;     // unused: films clamp to the edge\n"
    "    int   mode;\n"
    "    int   pad0;\n"
    "} pc;\n"
    "\n"
    "layout(local_size_x = 16, local_size_y = 16) in;\n"
    "\n"
    "ivec2 edge(ivec2 p, ivec2 s)\n"
    "{\n"
    "    return clamp(p, ivec2(0), s - ivec2(1));\n"
    "}\n"
    "\n"
    "// AMD FidelityFX Super Resolution 1.0.2, EASU, on the luma of a film frame,\n"
    "// 2x (BO-136, graphics.film_upscale Cheap). The filter is AMD's (MIT,\n"
    "// Copyright (c) 2021 Advanced Micro Devices, Inc.), as agyild's mpv port\n"
    "// runs it on one plane (MIT); written here as a compute pass: the 12 taps\n"
    "// are texel fetches of the frame (source, binding 0) turned into BT.709\n"
    "// luma, the edge rule clamps. Output: the 2x luma (x), destination.\n"
    "layout(set = 0, binding = 0) uniform sampler2D source;\n"
    "layout(set = 0, binding = 4, rgba16f) writeonly uniform image2D destination;\n"
    "\n"
    "float L(ivec2 p)\n"
    "{\n"
    "    return dot(texelFetch(source, edge(p, pc.size), 0).rgb, vec3(0.2126, 0.7152, 0.0722));\n"
    "}\n"
    "\n"
    "float APrxLoRcpF1(float a) { return uintBitsToFloat(uint(0x7ef07ebb) - floatBitsToUint(a)); }\n"
    "float APrxLoRsqF1(float a) { return uintBitsToFloat(uint(0x5f347d74) - (floatBitsToUint(a) >> uint(1))); }\n"
    "\n"
    "void FsrEasuTap(inout float aC, inout float aW, vec2 off, vec2 dir, vec2 len, float lob,\n"
    "                float clp, float c)\n"
    "{\n"
    "    vec2 v;\n"
    "    v.x = (off.x * ( dir.x)) + (off.y * dir.y);\n"
    "    v.y = (off.x * (-dir.y)) + (off.y * dir.x);\n"
    "    v *= len;\n"
    "    float d2 = min(v.x * v.x + v.y * v.y, clp);\n"
    "    float wB = (2.0 / 5.0) * d2 + -1.0;\n"
    "    float wA = lob * d2 + -1.0;\n"
    "    wB *= wB;\n"
    "    wA *= wA;\n"
    "    wB = (25.0 / 16.0) * wB + (-(25.0 / 16.0 - 1.0));\n"
    "    float w = wB * wA;\n"
    "    aC += c * w;\n"
    "    aW += w;\n"
    "}\n"
    "\n"
    "void FsrEasuSet(inout vec2 dir, inout float len, float w,\n"
    "                float lA, float lB, float lC, float lD, float lE)\n"
    "{\n"
    "    float dc = lD - lC;\n"
    "    float cb = lC - lB;\n"
    "    float lenX = APrxLoRcpF1(max(abs(dc), abs(cb)));\n"
    "    float dirX = lD - lB;\n"
    "    lenX = clamp(abs(dirX) * lenX, 0.0, 1.0);\n"
    "    lenX *= lenX;\n"
    "    float ec = lE - lC;\n"
    "    float ca = lC - lA;\n"
    "    float lenY = APrxLoRcpF1(max(abs(ec), abs(ca)));\n"
    "    float dirY = lE - lA;\n"
    "    lenY = clamp(abs(dirY) * lenY, 0.0, 1.0);\n"
    "    lenY *= lenY;\n"
    "    dir += vec2(dirX, dirY) * w;\n"
    "    len += dot(vec2(w), vec2(lenX, lenY));\n"
    "}\n"
    "\n"
    "void main()\n"
    "{\n"
    "    ivec2 q = ivec2(gl_GlobalInvocationID.xy);\n"
    "    if (any(greaterThanEqual(q, pc.size * 2)))\n"
    "        return;\n"
    "    //    b c\n"
    "    //  e f g h\n"
    "    //  i j k l\n"
    "    //    n o      F = the texel at fp\n"
    "    vec2 pp = (vec2(q) + 0.5) * 0.5 - 0.5;\n"
    "    vec2 fpf = floor(pp);\n"
    "    pp -= fpf;\n"
    "    ivec2 fp = ivec2(fpf);\n"
    "    float bL = L(fp + ivec2(0, -1)), cL = L(fp + ivec2(1, -1));\n"
    "    float eL = L(fp + ivec2(-1, 0)), fL = L(fp), gL = L(fp + ivec2(1, 0)), hL = L(fp + ivec2(2, 0));\n"
    "    float iL = L(fp + ivec2(-1, 1)), jL = L(fp + ivec2(0, 1)), kL = L(fp + ivec2(1, 1));\n"
    "    float lL = L(fp + ivec2(2, 1));\n"
    "    float nL = L(fp + ivec2(0, 2)), oL = L(fp + ivec2(1, 2));\n"
    "\n"
    "    vec2 dir = vec2(0.0);\n"
    "    float len = 0.0;\n"
    "    FsrEasuSet(dir, len, (1.0 - pp.x) * (1.0 - pp.y), bL, eL, fL, gL, jL);\n"
    "    FsrEasuSet(dir, len, pp.x * (1.0 - pp.y), cL, fL, gL, hL, kL);\n"
    "    FsrEasuSet(dir, len, (1.0 - pp.x) * pp.y, fL, iL, jL, kL, nL);\n"
    "    FsrEasuSet(dir, len, pp.x * pp.y, gL, jL, kL, lL, oL);\n"
    "\n"
    "    vec2 dir2 = dir * dir;\n"
    "    float dirR = dir2.x + dir2.y;\n"
    "    bool zro = dirR < (1.0 / 32768.0);\n"
    "    dirR = APrxLoRsqF1(dirR);\n"
    "    dirR = zro ? 1.0 : dirR;\n"
    "    dir.x = zro ? 1.0 : dir.x;\n"
    "    dir *= vec2(dirR);\n"
    "    len = len * 0.5;\n"
    "    len *= len;\n"
    "    float stretch = (dir.x * dir.x + dir.y * dir.y) * APrxLoRcpF1(max(abs(dir.x), abs(dir.y)));\n"
    "    vec2 len2 = vec2(1.0 + (stretch - 1.0) * len, 1.0 + -0.5 * len);\n"
    "    float lob = 0.5 + ((1.0 / 4.0 - 0.04) - 0.5) * len;\n"
    "    float clp = APrxLoRcpF1(lob);\n"
    "\n"
    "    float aC = 0.0, aW = 0.0;\n"
    "    FsrEasuTap(aC, aW, vec2( 0.0, -1.0) - pp, dir, len2, lob, clp, bL);\n"
    "    FsrEasuTap(aC, aW, vec2( 1.0, -1.0) - pp, dir, len2, lob, clp, cL);\n"
    "    FsrEasuTap(aC, aW, vec2(-1.0,  1.0) - pp, dir, len2, lob, clp, iL);\n"
    "    FsrEasuTap(aC, aW, vec2( 0.0,  1.0) - pp, dir, len2, lob, clp, jL);\n"
    "    FsrEasuTap(aC, aW, vec2( 0.0,  0.0) - pp, dir, len2, lob, clp, fL);\n"
    "    FsrEasuTap(aC, aW, vec2(-1.0,  0.0) - pp, dir, len2, lob, clp, eL);\n"
    "    FsrEasuTap(aC, aW, vec2( 1.0,  1.0) - pp, dir, len2, lob, clp, kL);\n"
    "    FsrEasuTap(aC, aW, vec2( 2.0,  1.0) - pp, dir, len2, lob, clp, lL);\n"
    "    FsrEasuTap(aC, aW, vec2( 2.0,  0.0) - pp, dir, len2, lob, clp, hL);\n"
    "    FsrEasuTap(aC, aW, vec2( 1.0,  0.0) - pp, dir, len2, lob, clp, gL);\n"
    "    FsrEasuTap(aC, aW, vec2( 1.0,  2.0) - pp, dir, len2, lob, clp, oL);\n"
    "    FsrEasuTap(aC, aW, vec2( 0.0,  2.0) - pp, dir, len2, lob, clp, nL);\n"
    "    float y = aC / aW;\n"
    "    // Dering: within the four nearest texels.\n"
    "    y = clamp(y, min(min(fL, gL), min(jL, kL)), max(max(fL, gL), max(jL, kL)));\n"
    "    imageStore(destination, q, vec4(clamp(y, 0.0, 1.0), 0.0, 0.0, 1.0));\n"
    "}\n";

static const char k_film_rcas_glsl[] =
    "// BO-136 film filters: the parameters every pass takes (the same block as\n"
    "// the texture upscaler's passes, so both backends bind them alike). MIT.\n"
    "#version 450\n"
    "layout(push_constant) uniform UpParams {\n"
    "    ivec2 origin;   // unused here (whole-image dispatches)\n"
    "    ivec2 size;     // the input image's size\n"
    "    ivec2 wrap;     // unused: films clamp to the edge\n"
    "    int   mode;\n"
    "    int   pad0;\n"
    "} pc;\n"
    "\n"
    "layout(local_size_x = 16, local_size_y = 16) in;\n"
    "\n"
    "ivec2 edge(ivec2 p, ivec2 s)\n"
    "{\n"
    "    return clamp(p, ivec2(0), s - ivec2(1));\n"
    "}\n"
    "\n"
    "// AMD FidelityFX Super Resolution 1.0.2, RCAS (sharpening, with its noise\n"
    "// guard), on the 2x luma EASU made (BO-136). AMD's filter (MIT, Copyright\n"
    "// (c) 2021 Advanced Micro Devices, Inc.), as agyild's mpv port runs it on\n"
    "// one plane (MIT), sharpness 0.2 stops; a compute pass here. size: the 2x\n"
    "// image's.\n"
    "layout(set = 0, binding = 0, rgba16f) readonly uniform image2D luma2x;\n"
    "layout(set = 0, binding = 4, rgba16f) writeonly uniform image2D destination;\n"
    "\n"
    "#define SHARPNESS 0.2\n"
    "#define FSR_RCAS_LIMIT (0.25 - (1.0 / 16.0))\n"
    "\n"
    "float APrxMedRcpF1(float a)\n"
    "{\n"
    "    float b = uintBitsToFloat(uint(0x7ef19fff) - floatBitsToUint(a));\n"
    "    return b * (-b * a + 2.0);\n"
    "}\n"
    "float AMax3F1(float x, float y, float z) { return max(x, max(y, z)); }\n"
    "float AMin3F1(float x, float y, float z) { return min(x, min(y, z)); }\n"
    "\n"
    "float T(ivec2 p) { return imageLoad(luma2x, edge(p, pc.size)).x; }\n"
    "\n"
    "void main()\n"
    "{\n"
    "    ivec2 p = ivec2(gl_GlobalInvocationID.xy);\n"
    "    if (any(greaterThanEqual(p, pc.size)))\n"
    "        return;\n"
    "    //    b\n"
    "    //  d e f\n"
    "    //    h\n"
    "    float b = T(p + ivec2(0, -1)), d = T(p + ivec2(-1, 0)), e = T(p);\n"
    "    float f = T(p + ivec2(1, 0)), h = T(p + ivec2(0, 1));\n"
    "    float mn1L = min(AMin3F1(b, d, f), h);\n"
    "    float mx1L = max(AMax3F1(b, d, f), h);\n"
    "    vec2 peakC = vec2(1.0, -1.0 * 4.0);\n"
    "    float hitMinL = min(mn1L, e) / (4.0 * mx1L);\n"
    "    float hitMaxL = (peakC.x - max(mx1L, e)) / (4.0 * mn1L + peakC.y);\n"
    "    float lobeL = max(-hitMinL, hitMaxL);\n"
    "    float lobe = max(-FSR_RCAS_LIMIT, min(lobeL, 0.0)) * exp2(-clamp(SHARPNESS, 0.0, 2.0));\n"
    "    float nz = 0.25 * b + 0.25 * d + 0.25 * f + 0.25 * h - e;\n"
    "    nz = clamp(abs(nz) * APrxMedRcpF1(AMax3F1(AMax3F1(b, d, e), f, h)\n"
    "                                      - AMin3F1(AMin3F1(b, d, e), f, h)), 0.0, 1.0);\n"
    "    nz = -0.5 * nz + 1.0;\n"
    "    lobe *= nz;\n"
    "    float rcpL = APrxMedRcpF1(4.0 * lobe + 1.0);\n"
    "    float y = (lobe * b + lobe * d + lobe * h + lobe * f + e) * rcpL;\n"
    "    imageStore(destination, p, vec4(clamp(y, 0.0, 1.0), 0.0, 0.0, 1.0));\n"
    "}\n";

static const char k_film_recombine_glsl[] =
    "// BO-136 film filters: the parameters every pass takes (the same block as\n"
    "// the texture upscaler's passes, so both backends bind them alike). MIT.\n"
    "#version 450\n"
    "layout(push_constant) uniform UpParams {\n"
    "    ivec2 origin;   // unused here (whole-image dispatches)\n"
    "    ivec2 size;     // the input image's size\n"
    "    ivec2 wrap;     // unused: films clamp to the edge\n"
    "    int   mode;\n"
    "    int   pad0;\n"
    "} pc;\n"
    "\n"
    "layout(local_size_x = 16, local_size_y = 16) in;\n"
    "\n"
    "ivec2 edge(ivec2 p, ivec2 s)\n"
    "{\n"
    "    return clamp(p, ivec2(0), s - ivec2(1));\n"
    "}\n"
    "\n"
    "// A film frame's 2x colour from its 2x luma (BO-136, Cheap; own code, MIT):\n"
    "// the bilinear 2x of the (deblocked) frame, moved by the filter's luma minus\n"
    "// its own (BT.709), as the texture upscaler's recombine does; alpha the\n"
    "// frame's, nearest. source: the frame (binding 0), luma2x (binding 1) the\n"
    "// 2x luma; size: the frame's.\n"
    "layout(set = 0, binding = 0) uniform sampler2D source;\n"
    "layout(set = 0, binding = 1, rgba16f) readonly uniform image2D luma2x;\n"
    "layout(set = 0, binding = 4, rgba8) writeonly uniform image2D destination;\n"
    "\n"
    "vec4 src(ivec2 p) { return texelFetch(source, edge(p, pc.size), 0); }\n"
    "\n"
    "void main()\n"
    "{\n"
    "    ivec2 q = ivec2(gl_GlobalInvocationID.xy);\n"
    "    if (any(greaterThanEqual(q, pc.size * 2)))\n"
    "        return;\n"
    "    float ym = imageLoad(luma2x, q).x;\n"
    "    vec2 f = (vec2(q) + 0.5) * 0.5 - 0.5;\n"
    "    ivec2 i0 = ivec2(floor(f));\n"
    "    vec2 t = f - vec2(i0);\n"
    "    vec3 rgb = mix(mix(src(i0).rgb, src(i0 + ivec2(1, 0)).rgb, t.x),\n"
    "                   mix(src(i0 + ivec2(0, 1)).rgb, src(i0 + ivec2(1, 1)).rgb, t.x), t.y);\n"
    "    float yb = dot(rgb, vec3(0.2126, 0.7152, 0.0722));\n"
    "    rgb = clamp(rgb + (clamp(ym, 0.0, 1.0) - yb), 0.0, 1.0);\n"
    "    imageStore(destination, q, vec4(rgb, src(q >> 1).a));\n"
    "}\n";

